public class InefficientWeightDetector extends LayoutDetector {
    private static final Implementation IMPLEMENTATION = new Implementation(
            InefficientWeightDetector.class,
            Scope.RESOURCE_FILE_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "InefficientWeight",
            "Inefficient layout weight",
            "When using a `layout_weight` on a `View` ...",
            Category.PERFORMANCE,
            3,
            Severity.WARNING,
            IMPLEMENTATION);

    public static final Issue ISSUE_NESTED_WEIGHTS = Issue.create(
            "NestedWeights",
            "Nested layout weights",
            "Layout weights require a widget to be measured twice. When a `LinearLayout` with non-zero weights is nested inside another `LinearLayout` with non-zero weights, then the number of measurements increase exponentially.",
            Category.PERFORMANCE,
            4,
            Severity.WARNING,
            IMPLEMENTATION);

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(LINEAR_LAYOUT);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        // Nested weights
        if (element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT)) {
            String weight = element.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT);
            if (weight != null && !weight.isEmpty() && !weight.equals("0") && !weight.equals("0.0")) {
                Element parent = getParentLinearLayout(element);
                while (parent != null) {
                    if (parent.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT)) {
                        String parentWeight = parent.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT);
                        if (parentWeight != null && !parentWeight.isEmpty() && !parentWeight.equals("0") && !parentWeight.equals("0.0")) {
                            context.report(ISSUE_NESTED_WEIGHTS, element, context.getLocation(element), "Nested layout weights are inefficient");
                            break;
                        }
                    }
                    parent = getParentLinearLayout(parent);
                }
            }
        }

        // Inefficient weight
        if (element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT)) {
            String orientation = element.getAttributeNS(ANDROID_URI, ATTR_ORIENTATION);
            boolean vertical = orientation == null || orientation.isEmpty() || orientation.equals(VALUE_VERTICAL);
            String dimension = vertical ? ATTR_LAYOUT_HEIGHT : ATTR_LAYOUT_WIDTH;
            if (VALUE_WRAP_CONTENT.equals(element.getAttributeNS(ANDROID_URI, dimension))) {
                context.report(ISSUE, element, context.getLocation(element), String.format("Use a `layout_height` of `0dp` instead of `%s` for better performance", VALUE_WRAP_CONTENT));
            }
        }
    }

    private static Element getParentLinearLayout(Element element) {
        Element parent = element.getParentNode() instanceof Element ? (Element) element.getParentNode() : null;
        while (parent != null && !LINEAR_LAYOUT.equals(parent.getTagName())) {
            parent = parent.getParentNode() instanceof Element ? (Element) parent.getParentNode() : null;
        }
        return parent;
    }
}

