public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
    // Nested weights
    if (element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT)) {
        String weight = element.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT);
        if (weight != null && !weight.isEmpty() && !weight.equals("0") && !weight.equals("0.0")) {
            Element parent = element.getParentNode() instanceof Element ? (Element) element.getParentNode() : null;
            while (parent != null) {
                if (parent.getTagName().equals(LINEAR_LAYOUT) && parent.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT)) {
                    String parentWeight = parent.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT);
                    if (parentWeight != null && !parentWeight.isEmpty() && !parentWeight.equals("0") && !parentWeight.equals("0.0")) {
                        context.report(ISSUE_NESTED_WEIGHTS, element, context.getLocation(element), "Nested layout weights are inefficient");
                        break;
                    }
                }
                parent = parent.getParentNode() instanceof Element ? (Element) parent.getParentNode() : null;
            }
        }
    }

    // Inefficient weight: when a child of a LinearLayout has a weight and its
    // dimension along the orientation is wrap_content
    String orientation = element.getAttributeNS(ANDROID_URI, ATTR_ORIENTATION);
    boolean vertical = orientation == null || orientation.isEmpty() || orientation.equals(VALUE_VERTICAL);
    String dimension = vertical ? ATTR_LAYOUT_HEIGHT : ATTR_LAYOUT_WIDTH;
    Node child = element.getFirstChild();
    while (child != null) {
        if (child.getNodeType() == Node.ELEMENT_NODE) {
            Element childElement = (Element) child;
            if (childElement.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT)) {
                String weight = childElement.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT);
                if (weight != null && !weight.isEmpty() && !weight.equals("0") && !weight.equals("0.0")) {
                    if (VALUE_WRAP_CONTENT.equals(childElement.getAttributeNS(ANDROID_URI, dimension))) {
                        context.report(ISSUE, childElement, context.getLocation(childElement), String.format("Use a `%s` of `0dp` instead of `%s` for better performance", dimension, VALUE_WRAP_CONTENT));
                    }
                }
            }
        }
        child = child.getNextSibling();
    }
}
```

