                    break;
                }
                parent = parent.getParentNode();
            }
        }

        String orientation = element.getAttributeNS(ANDROID_URI, ATTR_ORIENTATION);
        boolean vertical =
                orientation == null || orientation.isEmpty() || VALUE_VERTICAL.equals(orientation);
        String dimension = vertical ? ATTR_LAYOUT_HEIGHT : ATTR_LAYOUT_WIDTH;

        Node child = element.getFirstChild();
        while (child != null) {
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                Element childElement = (Element) child;
                if (hasNonZeroWeight(childElement)
                        && VALUE_WRAP_CONTENT.equals(
                                childElement.getAttributeNS(ANDROID_URI, dimension))) {
                    context.report(
                            ISSUE,
                            childElement,
                            context.getLocation(childElement),
                            String.format(
                                    "Use a `%s` of `0dp` instead of `%s` for better performance",
                                    dimension, VALUE_WRAP_CONTENT));
                }
            }
            child = child.getNextSibling();
        }
    }

    private static boolean hasNonZeroWeight(@NonNull Element element) {
        if (!element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT)) {
            return false;
        }
        String weight = element.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT);
        if (weight == null || weight.isEmpty()) {
            return false;
        }
        try {
            return Float.parseFloat(weight) != 0f;
        } catch (NumberFormatException e) {
            return false;
        }
    }

    private static boolean hasWeightedChild(@NonNull Element element) {
        Node child = element.getFirstChild();
        while (child != null) {
            if (child.getNodeType() == Node.ELEMENT_NODE) {
