import static com.android.SdkConstants.ANDROID_URI;
import static com.android.SdkConstants.ATTR_LAYOUT_HEIGHT;
import static com.android.SdkConstants.ATTR_LAYOUT_WEIGHT;
import static com.android.SdkConstants.ATTR_LAYOUT_WIDTH;
import static com.android.SdkConstants.ATTR_ORIENTATION;
import static com.android.SdkConstants.LINEAR_LAYOUT;
import static com.android.SdkConstants.VALUE_VERTICAL;
import static com.android.SdkConstants.VALUE_WRAP_CONTENT;

import com.android.annotations.NonNull;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.LayoutDetector;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import java.util.Collection;
import java.util.Collections;
import org.w3c.dom.Element;
import org.w3c.dom.Node;

public class InefficientWeightDetector extends LayoutDetector {
    private static final Implementation IMPLEMENTATION = new Implementation(
            InefficientWeightDetector.class,
            Scope.RESOURCE_FILE_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "InefficientWeight",
            "Inefficient layout weight",
            "When using a `layout_weight` on a child of a `LinearLayout`, the child "
                    + "should have a dimension of `0dp` along the orientation axis. "
                    + "Using `wrap_content` forces the child to be measured twice: once "
                    + "to compute its intrinsic size and once to distribute the remaining "
                    + "space according to the weight.",
            Category.PERFORMANCE,
            3,
            Severity.WARNING,
            IMPLEMENTATION);

    public static final Issue ISSUE_NESTED_WEIGHTS = Issue.create(
            "NestedWeights",
            "Nested layout weights",
            "Layout weights require a widget to be measured twice. When a `LinearLayout` "
                    + "with non-zero weights is nested inside another `LinearLayout` with "
                    + "non-zero weights, then the number of measurements increase "
                    + "exponentially.",
            Category.PERFORMANCE,
            4,
            Severity.WARNING,
            IMPLEMENTATION);

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(LINEAR_LAYOUT);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (hasWeight(element)) {
            Node parent = element.getParentNode();
            while (parent != null && parent.getNodeType() == Node.ELEMENT_NODE) {
                Element parentElement = (Element) parent;
                if (LINEAR_LAYOUT.equals(parentElement.getTagName()) && hasWeight(parentElement)) {
                    context.report(
                            ISSUE_NESTED_WEIGHTS,
                            element,
                            context.getLocation(element),
                            "Nested layout weights are inefficient");
                    break;
                }
                parent = parent.getParentNode();
            }
        }

        String orientation = element.getAttributeNS(ANDROID_URI, ATTR_ORIENTATION);
        boolean vertical =
                orientation == null || orientation.isEmpty() || VALUE_VERTICAL.equals(orientation);
        String dimension = vertical ? ATTR_LAYOUT_HEIGHT : ATTR_LAYOUT_WIDTH;

        Node child = element.getFirstChild();
        while (child != null) {
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                Element childElement = (Element) child;
                if (hasWeight(childElement)
                        && VALUE_WRAP_CONTENT.equals(
                                childElement.getAttributeNS(ANDROID_URI, dimension))) {
                    context.report(
                            ISSUE,
                            childElement,
                            context.getLocation(childElement),
                            String.format(
                                    "Use a `%s` of `0dp` instead of `%s` for better performance",
                                    dimension, VALUE_WRAP_CONTENT));
                }
            }
            child = child.getNextSibling();
        }
    }

    private static boolean hasWeight(@NonNull Element element) {
        if (!element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT)) {
            return false;
        }
        String weight = element.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT);
        if (weight == null || weight.isEmpty()) {
            return false;
        }
        try {
            return Float.parseFloat(weight) != 0f;
        } catch (NumberFormatException e) {
            return false;
        }
    }
}
