public class InefficientWeightDetector extends LayoutDetector {
    public static final Issue ISSUE = Issue.create(...);
    public static final Issue ISSUE_NESTED_WEIGHTS = Issue.create(...);

    @Override
    public Collection<String> getApplicableElements() {
        return Collections.singletonList(LINEAR_LAYOUT);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (hasWeight(element)) {
            Node parent = element.getParentNode();
            while (parent != null && parent.getNodeType() == Node.ELEMENT_NODE) {
                Element parentElement = (Element) parent;
                if (LINEAR_LAYOUT.equals(parentElement.getTagName()) && hasWeight(parentElement)) {
                    context.report(ISSUE_NESTED_WEIGHTS, element, context.getLocation(element),
                            "Nested layout weights are inefficient");
                    break;
                }
                parent = parent.getParentNode();
            }
        }

        String orientation = element.getAttributeNS(ANDROID_URI, ATTR_ORIENTATION);
        boolean vertical = VALUE_VERTICAL.equals(orientation);
        String dimension = vertical ? ATTR_LAYOUT_HEIGHT : ATTR_LAYOUT_WIDTH;

        Node child = element.getFirstChild();
        while (child != null) {
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                Element childElement = (Element) child;
                if (hasWeight(childElement)
                        && VALUE_WRAP_CONTENT.equals(
                                childElement.getAttributeNS(ANDROID_URI, dimension))) {
                    context.report(ISSUE, childElement, context.getLocation(childElement),
                            String.format(
                                    "Use a `%s` of `0dp` instead of `%s` for better performance",
                                    dimension, VALUE_WRAP_CONTENT));
                }
            }
            child = child.getNextSibling();
        }
    }

    private static boolean hasWeight(@NonNull Element element) {
        if (!element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT)) {
            return false;
        }
        String weight = element.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WEIGHT);
        if (weight == null || weight.isEmpty()) {
            return false;
        }
        try {
            return Float.parseFloat(weight) != 0f;
        } catch (NumberFormatException e) {
            return false;
        }
    }
}
